import { useEffect, useState } from "react";
import axios from "axios";
import EmployeeList from "./EmployeeList";
import "bootstrap/dist/css/bootstrap.min.css";

function DepartmentList() {
  const [department, setDepartment] = useState([]);
  const [employee, setEmployee] = useState([]);
  const [selectedDeptId, setSelectedDeptId] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      const deptResponse = await axios.get("http://localhost:9999/departments");
      setDepartment(deptResponse.data);

      const empResponse = await axios.get("http://localhost:9999/employees");
      setEmployee(empResponse.data);
    };
    fetchData();
  }, []);

  // Get manager name by managerId
  const getManagerName = (managerId) => {
    const manager = employee.find(
      (emp) => String(emp.id) === String(managerId)
    );
    if (manager) {
      return manager.empName.firstName + " " + manager.empName.lastName;
    } else {
      return "";
    }
  };

  const handleViewClick = (departmentId) => {
    setSelectedDeptId(departmentId);
  };

  return (
    <div>
      <h2 style={{ textAlign: "center" }}>COMPANY MANAGEMENT</h2>
      <div style={{ display: "flex", gap: "20px", padding: "10px" }}>
        {/* Department List */}
        <div style={{ minWidth: "280px" }}>
          <h3>Department List</h3>
          <table border={"1"} style={{ borderCollapse: "collapse", width: "100%" }}>
            <thead>
              <tr>
                <th style={{ padding: "6px 10px" }}>DepName</th>
                <th style={{ padding: "6px 10px" }}>Manager</th>
                <th style={{ padding: "6px 10px" }}>Employees</th>
              </tr>
            </thead>
            <tbody>
              {department.map((dept) => (
                <tr key={dept.id}>
                  <td style={{ padding: "6px 10px" }}>{dept.depName}</td>
                  <td style={{ padding: "6px 10px" }}>
                    {getManagerName(dept.managerId)}
                  </td>
                  <td style={{ padding: "6px 10px" }}>
                    <button
                      onClick={() => handleViewClick(dept.id)}
                      style={{
                        backgroundColor:
                          selectedDeptId === dept.id ? "#0a58ca" : "#0d6efd",
                        color: "white",
                        border: "none",
                        padding: "4px 10px",
                        borderRadius: "4px",
                        cursor: "pointer",
                      }}
                    >
                      View
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Employee List - shown when a department is selected */}
        {selectedDeptId && (
          <div style={{ flex: 1 }}>
            <EmployeeList departmentId={selectedDeptId} />
          </div>
        )}
      </div>
    </div>
  );
}

export default DepartmentList;
